const rows = $input.first().json.rows;
const projectId = rows[0].project_id;

const failedItems = rows.map(row => ({
  asset_id: row.asset_id,
  shot_id: row.shot_id,
  project_id: projectId,
  asset_type: row.asset_type,
  image_path: row.image_path,
  current_score: row.overall_score || row.quality_score || 0,
  issues: row.issues || [],
  repair_notes: row.repair_notes,
  shot_number: row.shot_number,
  description: row.description,
  positive_prompt: row.positive_prompt,
  negative_prompt: row.negative_prompt,
  repair_attempts: 0,
  max_repair_attempts: 3
}));

return [{
  json: {
    project_id: projectId,
    failed_items: failedItems,
    total_failed: failedItems.length
  }
}];

const responseText = $input.first().json.response || '{}';
let strategyData = [];

try {
  const jsonMatch = responseText.match(/\[[\s\S]*\]/);
  if (jsonMatch) {
    strategyData = JSON.parse(jsonMatch[0]);
  } else {
    const objMatch = responseText.match(/\{[\s\S]*\}/);
    if (objMatch) {
      const parsed = JSON.parse(objMatch[0]);
      strategyData = Object.entries(parsed).map(([key, val]) => ({ asset_id: key, ...val }));
    }
  }
} catch (e) {
  strategyData = [];
}

const projectId = $('Execute Logic').item.json.project_id;
const failedItems = $('Execute Logic').item.json.failed_items;

const repairJobs = [];
let escalated = 0, queuedForRepair = 0;

for (const sd of strategyData) {
  const item = failedItems.find(f => f.asset_id === sd.asset_id);
  if (!item) continue;

  if (sd.strategy === 'escalate' || item.repair_attempts >= item.max_repair_attempts) {
    escalated++;
    continue;
  }

  queuedForRepair++;
  repairJobs.push({
    json: {
      asset_id: sd.asset_id,
      project_id: projectId,
      shot_id: item.shot_id,
      strategy: sd.strategy,
      adjusted_positive_prompt: sd.adjusted_positive_prompt || item.positive_prompt,
      adjusted_negative_prompt: sd.adjusted_negative_prompt || item.negative_prompt,
      param_adjustments: JSON.stringify(sd.param_adjustments || {}),
      repair_confidence: sd.repair_confidence || 5,
      reason: sd.reason || '',
      previous_score: item.current_score
    }
  });
}

return [{
  json: {
    project_id: projectId,
    repair_jobs: repairJobs,
    escalated: escalated,
    queued_for_repair: queuedForRepair,
    total_failed: failedItems.length
  }
}];

